/**
 * Phase 21.6 — account linking needs proof the caller cannot fabricate.
 *
 * The plan of the rejection this covers:
 *  - a wrong link code must be refused (403);
 *  - the code is generated by the backend and never appears in the response;
 *  - a provider proof can only come from a token `socialLogin` verified.
 */
import mongoose, { Connection } from 'mongoose';
import { MongoMemoryServer } from 'mongodb-memory-server';
import { AccountLinkingService } from './account-linking.service';
import type { MailService } from '../mail/mail.module';

jest.setTimeout(120_000);

describe('Phase 21.6 account linking', () => {
  let mongo: MongoMemoryServer;
  let conn: Connection;
  let svc: AccountLinkingService;
  let sent: Array<{ to: string; body: string }>;
  let deliver: (to: string, body: string) => Promise<boolean>;

  beforeAll(async () => {
    mongo = await MongoMemoryServer.create({ instance: { launchTimeout: 60000 } });
    conn = await mongoose.createConnection(mongo.getUri(), { dbName: 'account-linking' }).asPromise();
  });
  afterAll(async () => { await conn.close(); await mongo.stop(); });

  beforeEach(async () => {
    for (const name of ['account_links', 'account_link_proofs', 'users', 'audit_logs']) {
      const exists = (await conn.db!.collections()).some((c) => c.collectionName === name);
      if (!exists) await conn.createCollection(name).catch(() => undefined);
      await conn.collection(name).deleteMany({});
    }
    await conn.collection('users').insertOne({ id: 'victim', role: 'patient' });
    sent = [];
    deliver = async (to, body) => { sent.push({ to, body }); return true; };
    const mail = { send: jest.fn(async (to: string, _s: string, body: string) => ({ ok: await deliver(to, body) })) } as unknown as MailService;
    svc = new AccountLinkingService(conn, mail);
  });

  /** The code of the mail that was just delivered (the newest one). */
  function codeFromMail(): string {
    expect(sent.length).toBeGreaterThan(0);
    const match = sent[sent.length - 1].body.match(/(\d{6})/);
    expect(match).toBeTruthy();
    return match![1];
  }

  it('a pending link is not confirmed by its id alone, nor by someone who is not the target', async () => {
    const { linked_account_id } = await svc.requestLink('attacker', 'victim', 'email', 'victim@example.test');
    await expect(svc.confirmLink(linked_account_id, 'attacker', { kind: 'email_code', code: codeFromMail() })).rejects.toThrow('link_caller_is_not_the_target');
    expect((await conn.collection('account_links').findOne({ id: linked_account_id }))?.status).toBe('pending');
    expect((await conn.collection('users').findOne({ id: 'victim' }))?.email).toBeUndefined();
  });

  it('refuses a link without any proof', async () => {
    const { linked_account_id } = await svc.requestLink('a', 'victim', 'email', 'v@example.test');
    await expect(svc.confirmLink(linked_account_id, 'victim', undefined as never)).rejects.toThrow(/link_confirmation_requires_proof/);
  });

  it('a wrong link code is a 403 Forbidden and changes nothing', async () => {
    const { linked_account_id } = await svc.requestLink('a', 'victim', 'email', 'victim@example.test');
    codeFromMail();
    let thrown: unknown;
    try {
      await svc.confirmLink(linked_account_id, 'victim', { kind: 'email_code', code: '000000' });
    } catch (e) { thrown = e; }
    // A real 403, not a 400 and not a 500.
    expect((thrown as { status?: number })?.status ?? (thrown as { getStatus?: () => number })?.getStatus?.()).toBe(403);
    expect((await conn.collection('account_links').findOne({ id: linked_account_id }))?.status).toBe('pending');
    expect((await conn.collection('users').findOne({ id: 'victim' }))?.email).toBeUndefined();
  });

  it('the correct code confirms and the address is only written then', async () => {
    const { linked_account_id, proof_sent_to } = await svc.requestLink('a', 'victim', 'email', 'victim@example.test');
    expect(proof_sent_to).toBe('email');
    const code = codeFromMail();
    await svc.confirmLink(linked_account_id, 'victim', { kind: 'email_code', code });
    const link = await conn.collection('account_links').findOne({ id: linked_account_id });
    expect(link?.status).toBe('active');
    expect((await conn.collection('users').findOne({ id: 'victim' }))?.email).toBe('victim@example.test');
    expect(await conn.collection('audit_logs').countDocuments({ action: 'account.linked' })).toBe(1);
  });

  it('the code never comes back to the caller', async () => {
    const result = await svc.requestLink('a', 'victim', 'email', 'victim@example.test');
    const serialised = JSON.stringify(result);
    const code = codeFromMail();
    expect(serialised).not.toContain(code);
    expect(Object.keys(result)).toEqual(['linked_account_id', 'proof_sent_to']);
  });

  it('the code is generated by the server: two links get two different codes', async () => {
    await svc.requestLink('a', 'victim', 'email', 'one@example.test');
    const first = codeFromMail();
    await svc.requestLink('a', 'victim', 'email', 'two@example.test');
    const second = codeFromMail();
    expect(first).not.toBe(second);
  });

  it('a proof is single-use and a failed delivery leaves no pending link', async () => {
    const { linked_account_id } = await svc.requestLink('a', 'victim', 'email', 'v@example.test');
    const code = codeFromMail();
    await svc.confirmLink(linked_account_id, 'victim', { kind: 'email_code', code });
    await expect(svc.confirmLink(linked_account_id, 'victim', { kind: 'email_code', code })).rejects.toThrow('link_not_pending');

    deliver = async () => false;
    await expect(svc.requestLink('a', 'victim', 'email', 'dead@example.test')).rejects.toThrow('link_code_delivery_failed');
    expect(await conn.collection('account_links').countDocuments({ provider_email: 'dead@example.test' })).toBe(0);
  });

  it('a provider link gets no code and no proof until socialLogin verifies a token', async () => {
    const { linked_account_id, proof_sent_to } = await svc.requestLink('me', 'victim', 'google', 'me@example.test');
    expect(proof_sent_to).toBe('provider_session');
    expect(sent).toHaveLength(0);

    // A body-supplied subject proves nothing.
    await expect(
      svc.confirmLink(linked_account_id, 'victim', { kind: 'verified_provider_session', verified_subject: 'google:me@example.test', method: 'google' }),
    ).rejects.toThrow('link_proof_missing');

    await svc.recordProviderProof(linked_account_id, 'google:me@example.test', 'google');
    await expect(
      svc.confirmLink(linked_account_id, 'victim', { kind: 'verified_provider_session', verified_subject: 'google:someone-else@example.test', method: 'google' }),
    ).rejects.toThrow('link_proof_subject_mismatch');
    await svc.confirmLink(linked_account_id, 'victim', { kind: 'verified_provider_session', verified_subject: 'google:me@example.test', method: 'google' });
    expect((await conn.collection('account_links').findOne({ id: linked_account_id }))?.status).toBe('active');
  });

  it('an emailed code cannot confirm a provider link, and vice versa', async () => {
    const google = await svc.requestLink('me', 'victim', 'google', 'g@example.test');
    await svc.recordProviderProof(google.linked_account_id, 'google:g@example.test', 'google');
    await expect(
      svc.confirmLink(google.linked_account_id, 'victim', { kind: 'email_code', code: '123456' }),
    ).rejects.toThrow('link_proof_kind_mismatch');
  });

  it('limits link requests to five an hour', async () => {
    for (let i = 0; i < 5; i += 1) {
      await svc.requestLink('me', 'victim', 'google', `p${i}@example.test`);
    }
    await expect(svc.requestLink('me', 'victim', 'google', 'p6@example.test')).rejects.toThrow('link_request_rate_limited');
  });

  it('never uses a placeholder provider identity', () => {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const src = require('fs').readFileSync(require.resolve('./account-linking.service'), 'utf8');
    expect(src).not.toMatch(/['"]user@(gmail|icloud)\.com['"]/);
  });
});